'use strict';

const icon = (name, size = '') => `<svg class="icon ${size}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const features = [
  {name:'Today, in focus',icon:'sun',category:'day',description:'Your priorities, commitments, agenda and follow-ups in one clear starting point.',details:['Choose three priorities for the day; see overdue, due-today and waiting-on work.','See agenda overlaps, flagged unread mail, source freshness and incomplete results.','Open a daily brief or end-of-day review with your saved work context.']},
  {name:'Commitments that keep moving',icon:'tasks',category:'day',description:'Capture a thought. Give it an owner, a next step and a useful reminder.',details:['Search and filter Open, Waiting on and Completed work; set priority, notes, due and follow-up dates.','Edit, complete, reschedule, delete or snooze. Daily, weekly and monthly tasks create their next occurrence on completion.','Review proposed task changes in chat. Optional macOS reminders can arrive while Puddle is closed. Owner fields record context; they do not send delegations.']},
  {name:'A calendar with breathing room',icon:'calendar',category:'day',description:'See the week, find a meeting slot and protect a little time to focus.',details:['Google Calendar agenda, week and month views, with up to ten selected calendars.','Working hours, meeting buffers, duration preferences, candidate slots and focus-time proposals.','Review create, edit and undo proposals with attendees and timezones. Provider revision checks protect calendar changes. Calendar results are bounded.']},
  {name:'A routine you can rely on',icon:'repeat',category:'day',description:'Scheduled read-only briefs and reviews, with a history you can come back to.',details:['Save scheduled briefings and reviews; pause them whenever you need.','Review persisted runs and missed or interrupted work.','Routines require the app or menu-bar process. Missed work is handled on next launch; routines do not change tasks or send messages.']},
  {name:'Context beyond the to-do list',icon:'folder',category:'day',description:'Keep projects, people, goals and decisions connected to the work they shape.',details:['Link project goals with commitments and meeting notes.','Save explicit people and VIP records, interactions, promises and talking points.','Record decisions with owners, options, rationale, evidence, review dates and outcomes.']},
  {name:'Your local conversation',icon:'chat',category:'assistant',description:'Think out loud, plan, write and ask questions with your choice of local AI provider.',details:['Stream replies, stop an answer, copy it, reuse a message as a draft or retry.','Search and reopen persistent conversations; keep the current chat when switching profiles.','Inspect tool receipts and give Puddle editable response preferences. AI conversations require a connected local model.']},
  {name:'Memory that feels personal',icon:'brain',category:'assistant',description:'The facts and preferences you choose to keep, carried into the next conversation.',details:['Learn supported personal facts and preferences from your own messages, with exact source quotes.','Inspect, update, manually save or forget memories; disable automatic learning at any time.','Mail, calendar and other external reference content are not personal-memory learning sources.']},
  {name:'An approach that fits',icon:'sliders',category:'assistant',description:'Personal, Developer or your own Custom profile. One shared workspace.',details:['Save independent goals, work context and additional guidance for each profile.','Create, rename, duplicate and remove inactive profiles, with up to fifty unique names.','Conversations, memory, tasks, meetings and connections remain shared; switching stops an unfinished reply.']},
  {name:'A voice when you want one',icon:'mic',category:'assistant',description:'Dictate a thought or hear a reply, with explicit on-device voice controls.',details:['Dictate in chat, review the text and choose when to send. Read answers aloud with an installed macOS voice.','Optional hold-to-talk System Dictation adds vocabulary and punctuation settings, original-field validation and a copy fallback.','Voice requires the relevant system permissions and supported installed language. No always-on listening or wake word.']},
  {name:'A shortcut to your workspace',icon:'search',category:'assistant',description:'Global search, quick capture and a contextual assistant keep useful things close.',details:['Use the command palette to find saved work and navigate quickly.','Open the assistant beside your work, or keep Puddle available in the menu bar.','Choose optional launch at login. Keyboard shortcuts and reduced-motion activity indicators support everyday use.']},
  {name:'Arrive with the context',icon:'calendar',category:'meetings',description:'Bring the agenda, earlier decisions and open actions into the room.',details:['Prepare from calendar details, saved agendas and matching previous notes.','See source-quoted decisions, questions and linked open commitments.','Link meetings to projects and recurring series; open supported Meet, Zoom, Teams and Webex join links.']},
  {name:'Notes that stay with the work',icon:'book',category:'meetings',description:'Write, search and revisit meeting notes without scattering them across tools.',details:['Keep drafts, saved notes and a floating meeting companion. Quit warns about unsaved meeting and development notes; edits typed during a save stay in the editor.','Import TXT, Markdown, VTT and SRT transcripts with supported timestamps and source labels.','Export Markdown, text, JSON or transcripts, including note-only exports. Connect notes with projects and recurring meetings.']},
  {name:'On-device transcription',icon:'mic',category:'meetings',description:'Capture the microphone and selected-app audio, then keep the useful words.',details:['Live transcription on macOS 26+ with a supported installed speech language and your audio permissions.','Keep timestamps and audio-source labels; those labels do not identify individual speakers.','Saved checkpoints support recovery after interruption. Capture starts explicitly.']},
  {name:'From discussion to next step',icon:'spark',category:'meetings',description:'Local summaries, decisions and action items, grounded in transcript quotes.',details:['Generate summaries, key decisions, open questions and action candidates locally.','Inspect exact supporting quotes rather than treating a summary as a source.','Review an extracted action before saving it as a commitment.']},
  {name:'Google Meet attendance',icon:'meet',category:'meetings',badge:'Experimental',description:'An explicitly started browser helper for the Google Meet join flow.',details:['Use a dedicated Chrome profile to open the join flow and observe admission or in-call controls.','Sign in and handle challenges yourself when needed. Camera and microphone are denied in the managed join flow.','Attendance needs validation against current Meet layouts and account rules. Nothing joins automatically from your calendar.']},
  {name:'An inbox with a next step',icon:'mail',category:'work',description:'Bring Gmail and Outlook into focus, from a useful summary to a reviewed reply.',details:['Switch accounts, search and filter recent cached messages, inspect bounded threads and explicitly selected attachments. Reading does not mark messages read.','Summarize, Ask Puddle, draft a task, compose, reply or forward. Review exact sends and organization actions.','Keep follow-ups, VIPs and local snooze; review newsletter unsubscribe options. The recent cache is not a full-mailbox archive.']},
  {name:'A project-aware assistant',icon:'code',category:'work',description:'Give the local model source context, so your project needs less explaining.',details:['Connect selected project folders, browse or search files, and cite numbered source.','Inspect Git status and working or staged text diffs. Save debugging, implementation and review sessions.','All project tools are read-only. Code changes, build/test execution and semantic indexing are not implemented.']},
  {name:'Your connected work sources',icon:'github',category:'work',description:'Read GitHub, Jira and Confluence context with links back to the evidence.',details:['Search GitHub issues and pull requests, read details and patch excerpts, and inspect reported CI checks when authorized.','Connect Jira Cloud and Confluence Cloud with Atlassian sign-in.','Choose your repositories and sites. These connectors search and read; they do not write issues, merge code or run checks.']},
  {name:'A home for local knowledge',icon:'book',category:'work',description:'Search selected files and folders, and bring cited passages into a conversation.',details:['Incrementally index supported text formats, PDF and DOCX with extraction limits.','Find cited passages, refresh changed files and remove deleted source content on refresh.','You choose the sources. OCR, spreadsheet workbook parsing and legacy Office formats are not included.']},
  {name:'A browser, with your say',icon:'globe',category:'work',description:'Read and summarize pages, with reviewed navigation and scrolling.',details:['Explicitly start a separate Chrome or Edge session through Cua Driver.','Review URL navigation and scrolling in chat. Clicking and typing are deferred; take over manually for links and forms. Driver setup and permissions are separate.','Save reading goals and progress, pause, and Continue from a fresh observation. Completion needs observed evidence.']},
  {name:'Actions you can inspect',icon:'check',category:'control',description:'A proposal first. An exact review. A receipt you can understand.',details:['Edit proposals and inspect concrete mail or calendar content before dispatch.','Keep durable dispatch intent, provider receipts and visible status.','An uncertain result is preserved and is not automatically replayed. Imported backups never execute saved actions.']},
  {name:'Privacy within reach',icon:'shield',category:'control',description:'Encrypted local storage and clear controls over history, sessions and connections.',details:['Keep workspace data encrypted on disk, with account credentials in macOS Keychain.','Save or discard existing notes before starting a private session. Ending the session discards its meeting and development drafts. App lock, retention and external-API pause remain under your control.','Your chosen local model server runs inference; optional connected services make external requests. Browser control follows Cua Driver permissions and privacy settings.']},
  {name:'Your work, recoverable',icon:'lock',category:'control',description:'Encrypted portable backups and a careful merge when you need a fresh start.',details:['Export saved work and profiles; account caches and Keychain secrets are excluded.','Preview a restore that preserves existing content and handles repeated imports.','Atomic saves and previous-state recovery protect local persistence. Restores do not replay actions, reconnect browser sessions or enable imported routines.']},
  {name:'A little help getting started',icon:'sliders',category:'control',description:'Guided local AI setup, useful diagnostics and a demo before you connect.',details:['Connect a local provider using its server address, optional model ID and API key.','Test the local chat and tool connection with synthetic verification.','Explore a labeled fixture demo. Puddle is built from source; public distribution and some real-device acceptance checks remain in progress.']}
];

let activeFilter = 'all';
const searchInput = document.querySelector('#feature-search');
const grid = document.querySelector('#feature-grid');
function renderFeatures() {
  const query = searchInput.value.trim().toLocaleLowerCase();
  const shown = features.filter(feature => (activeFilter === 'all' || feature.category === activeFilter) && [feature.name, feature.description, ...feature.details].join(' ').toLocaleLowerCase().includes(query));
  grid.innerHTML = shown.map(feature => `<article class="feature-card"><div class="feature-card-top"><span class="feature-icon">${icon(feature.icon)}</span><div><h3>${feature.name}</h3>${feature.badge ? `<span class="feature-badge">${feature.badge}</span>` : ''}</div></div><p>${feature.description}</p><details><summary>What’s included</summary><ul>${feature.details.map(detail => `<li>${detail}</li>`).join('')}</ul></details></article>`).join('');
  document.querySelector('#feature-count').textContent = `${shown.length} of ${features.length} features${activeFilter === 'all' && !query ? ' · Open a feature for the details' : ''}`;
  document.querySelector('#feature-empty').hidden = shown.length !== 0;
  document.querySelector('#reset-features').hidden = activeFilter === 'all' && !query;
  document.querySelectorAll('[data-filter]').forEach(button => {const selected = button.dataset.filter === activeFilter; button.classList.toggle('active', selected); button.setAttribute('aria-pressed', String(selected));});
}
document.querySelectorAll('[data-filter]').forEach(button => button.addEventListener('click', () => {activeFilter = button.dataset.filter; renderFeatures();}));
searchInput.addEventListener('input', renderFeatures);
function resetFeatures() {activeFilter = 'all'; searchInput.value = ''; renderFeatures();}
document.querySelector('#reset-features').addEventListener('click', resetFeatures);
document.querySelector('#empty-reset').addEventListener('click', () => {resetFeatures();searchInput.focus();});
document.querySelectorAll('[data-feature-jump]').forEach(link => link.addEventListener('click', () => {activeFilter = link.dataset.featureJump;searchInput.value = '';renderFeatures();}));
renderFeatures();

const menuButton=document.querySelector('.menu-toggle');
const mobileNav=document.querySelector('#mobile-nav');
function closeMenu(){mobileNav.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');}
menuButton.addEventListener('click',()=>{const open=mobileNav.hidden;mobileNav.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
mobileNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!mobileNav.hidden){closeMenu();menuButton.focus();}});
window.matchMedia('(min-width: 761px)').addEventListener('change',event=>{if(event.matches)closeMenu();});

let toastTimer;
function toast(message){const element=document.querySelector('#toast');element.textContent=message;element.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>element.classList.remove('visible'),3500);}
document.querySelector('#copy-install').addEventListener('click',async()=>{
  const commands=document.querySelector('#install-commands');
  try{if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(commands.textContent);document.querySelector('#copy-install span').textContent='Copied';toast('Installation commands copied.');setTimeout(()=>{document.querySelector('#copy-install span').textContent='Copy';},2500);}
  catch{const range=document.createRange();range.selectNodeContents(commands);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('Commands selected. Press ⌘C or Ctrl+C to copy.');}
});
